import glob, struct

# Let's test standard CRC-32 variants
# Poly 0x04C11DB7 (IEEE / POSIX / etc)
# Poly 0x1EDC6F41 (Castagnoli / CRC-32C)
# Poly 0xA833982B (Koopman)

def make_crc(poly, init, refin, refout, xorout):
    def crc(data):
        reg = init
        for b in data:
            if refin:
                # reflect byte
                b = int('{:08b}'.format(b)[::-1], 2)
            reg ^= (b << 24)
            for _ in range(8):
                if reg & 0x80000000:
                    reg = ((reg << 1) ^ poly) & 0xFFFFFFFF
                else:
                    reg = (reg << 1) & 0xFFFFFFFF
        if refout:
            reg = int('{:032b}'.format(reg)[::-1], 2)
        return reg ^ xorout
    return crc

with open('/app/samples/s06_empty.jrn', 'rb') as f:
    d = f.read()

payloads = [d[:-4], d[4:-4]]
expected = [struct.unpack('>I', d[-4:])[0], struct.unpack('<I', d[-4:])[0]]

polys = [0x04C11DB7, 0xEDB88320, 0x1EDC6F41, 0x82F63B78, 0xA833982B]
inits = [0, 0xFFFFFFFF]
xors = [0, 0xFFFFFFFF]

found = False
for p in payloads:
    for poly in polys:
        for init in inits:
            for xorout in xors:
                for refin in [False, True]:
                    for refout in [False, True]:
                        fn = make_crc(poly, init, refin, refout, xorout)
                        val = fn(p)
                        if val in expected:
                            print(f'Match! poly={hex(poly)} init={hex(init)} refin={refin} refout={refout} xorout={hex(xorout)} payload_len={len(p)} val={hex(val)}')
                            found = True
if not found:
    print('No standard CRC match')
"

