python3 -c "
import glob, json

currency_decimals = {}
for p in sorted(glob.glob('/app/samples/*.json')):
    with open(p) as f:
        j = json.load(f)
    for r in j['records']:
        curr = r['currency']
        amt = r['amount']
        if '.' in amt:
            decimals = len(amt.split('.')[1])
        else:
            decimals = 0
        if curr in currency_decimals:
            assert currency_decimals[curr] == decimals, f'Mismatch for {curr}: {currency_decimals[curr]} vs {decimals}'
        else:
            currency_decimals[curr] = decimals

print('Currencies and their decimal places:')
for c, d in sorted(currency_decimals.items()):
    print(f'  {c}: {d}')
"
